"""Keep the machine from idling into sleep while a long run (eval, check) is working.

A laptop that enters (Modern) Standby freezes the process: a run "hangs" for as long as the
machine sleeps. On Windows this asks the system to stay awake until the run ends; elsewhere
it does nothing. It never blocks the run: any failure is ignored. Closing the lid or pressing
the power button still sleeps the machine.
"""
from __future__ import annotations

import contextlib
import sys

ES_CONTINUOUS = 0x80000000
ES_SYSTEM_REQUIRED = 0x00000001


@contextlib.contextmanager
def keep_awake():
    active = False
    if sys.platform == "win32":
        try:
            import ctypes
            active = bool(ctypes.windll.kernel32.SetThreadExecutionState(
                ES_CONTINUOUS | ES_SYSTEM_REQUIRED))
        except Exception:
            active = False
    try:
        yield active
    finally:
        if active:
            try:
                import ctypes
                ctypes.windll.kernel32.SetThreadExecutionState(ES_CONTINUOUS)
            except Exception:
                pass

